#!/usr/bin/env python3
"""Build a portable, offline results page from measured CSV/JSON evidence."""
import base64
import csv
import json
from pathlib import Path
from presentation import STRATEGIES, WORKLOADS, state_name

ROOT = Path(__file__).resolve().parents[1]


def build():
    rows = list(csv.DictReader((ROOT/'reports/accuracy.csv').open()))
    verification = json.loads((ROOT/'reports/verification.json').read_text())
    manifest = json.loads((ROOT/'traces/manifest.json').read_text())
    units = json.loads((ROOT/'reports/unit_checks.json').read_text()) if (ROOT/'reports/unit_checks.json').exists() else None
    hardware_path = ROOT/'reports/synthesis/summary.csv'
    hardware = list(csv.DictReader(hardware_path.open())) if hardware_path.exists() else []
    groups = {}
    for name in dict.fromkeys(r['workload'] for r in rows):
        traces = {}
        for mode in STRATEGIES:
            path = ROOT/'reports/raw'/f'{name}_{mode}.csv'
            traces[mode] = [dict(r, state_label=state_name(mode, int(r['state'])))
                            for r in list(csv.DictReader(path.open()))[:12]]
        groups[name] = dict(label=WORKLOADS.get(name, name.replace('_',' ').title()),
            rows=[r for r in rows if r['workload']==name], traces=traces,
            outcomes=[b['taken'] for b in manifest['workloads'][name]['records'][:12]])
    data = json.dumps(dict(workloads=groups, strategies=STRATEGIES, verification=verification,
                           hardware=hardware, units=units)).replace('<', '\\u003c')
    def image(name, alt):
        image_path = ROOT/'reports/figures'/f'{name}.png'
        encoded = base64.b64encode(image_path.read_bytes()).decode()
        return f'<img loading="lazy" src="data:image/png;base64,{encoded}" alt="{alt}">'
    html = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Branch prediction results</title>
<style>
:root{--ink:#18243b;--muted:#526178;--purple:#6d37cc;--cyan:#087e96;--line:#dce2eb;--paper:#f4f6fa}
*{box-sizing:border-box}body{margin:0;color:var(--ink);background:var(--paper);font:16px/1.6 ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
header{background:#142039;color:white;padding:54px max(6vw,22px) 44px}header>div,main{max-width:1180px;margin:auto}.eyebrow{font-size:12px;font-weight:750;letter-spacing:.16em;text-transform:uppercase;color:#b5c7e7}
h1{font-size:clamp(32px,5vw,54px);letter-spacing:-.04em;line-height:1.12;margin:12px 0 18px}header p{color:#d9e3f4;max-width:750px;font-size:18px;margin:0}nav{display:flex;gap:24px;flex-wrap:wrap;margin-top:26px}nav a{color:white;text-underline-offset:5px;font-size:14px}
main{padding:32px 24px 64px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:16px;margin-bottom:38px}.stat{padding:18px 20px;background:white;border:1px solid var(--line);border-radius:12px}.stat strong{display:block;font-size:28px;letter-spacing:-.03em}.stat span{color:var(--muted);font-size:13px}
section{margin:34px 0 48px}h2{font-size:28px;line-height:1.2;letter-spacing:-.025em;margin:0 0 10px}h3{font-size:18px;margin:0 0 12px}p{margin:8px 0 16px}.muted,.caption{color:var(--muted)}.caption{font-size:13px}.toolbar{display:flex;justify-content:space-between;gap:22px;align-items:end;margin:24px 0}.toolbar label{display:block;font-size:13px;font-weight:700;margin-bottom:6px}
select,button{font:inherit;border:1px solid #b8c4d5;border-radius:8px;padding:10px 14px;background:white;color:var(--ink)}select{max-width:100%;min-width:260px}button{cursor:pointer}button:hover{border-color:var(--purple)}select:focus-visible,button:focus-visible,a:focus-visible{outline:3px solid #b9a1ee;outline-offset:3px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.card{background:white;border:1px solid var(--line);border-radius:13px;padding:24px;border-top:4px solid #64748b}.card.one_bit{border-top-color:var(--cyan)}.card.two_bit{border-top-color:var(--purple)}.metric{font-size:40px;font-weight:750;letter-spacing:-.04em;line-height:1.1;margin:14px 0 2px}.card dl{display:grid;grid-template-columns:1fr auto;gap:7px 14px;margin:20px 0 0;font-size:14px}.card dt{color:var(--muted)}.card dd{margin:0;font-variant-numeric:tabular-nums}.bar{height:6px;background:#edf0f5;border-radius:10px;overflow:hidden;margin-top:14px}.bar>i{display:block;height:100%;background:#64748b}.one_bit .bar>i{background:var(--cyan)}.two_bit .bar>i{background:var(--purple)}.insight{font-size:18px;margin:22px 0 8px;max-width:920px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:28px}.reading{max-width:920px}.frame{background:white;border:1px solid var(--line);border-radius:12px;padding:18px;margin:20px 0}.frame img{display:block;width:100%;height:auto}.tablewrap{overflow:auto;background:white;border:1px solid var(--line);border-radius:10px;margin:18px 0}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:14px}th,td{padding:13px 16px;text-align:left;border-bottom:1px solid #e7ebf2}th{background:#eef2f7;font-weight:700}tr:last-child td{border:0}.good{color:#17614e;font-weight:650}.bad{color:#a54a22;font-weight:650}details{margin:20px 0}summary{cursor:pointer;font-weight:650;color:var(--purple)}code{font-size:.9em;background:#e9edf5;border-radius:4px;padding:2px 5px}a{color:var(--purple)}.foot{border-top:1px solid var(--line);padding-top:24px;color:var(--muted);font-size:13px}#evidence{font-size:14px}.status{color:#17614e;font-weight:700}
@media(max-width:760px){header{padding-top:32px}.stats{grid-template-columns:repeat(2,1fr);gap:10px}.cards,.grid{grid-template-columns:1fr}.toolbar{align-items:start;flex-direction:column}.card{padding:20px}.metric{font-size:36px}main{padding:24px 18px}.stat{padding:14px}section{margin-bottom:36px}nav{gap:14px}}
@media print{body{background:white}header{background:white;color:black;padding:10px 0 24px}header p,.eyebrow{color:#333}nav,.toolbar button{display:none}main{padding:0}.card,.frame{break-inside:avoid}.tablewrap{overflow:visible}details{display:block}h2{break-after:avoid}}
</style></head><body>
<header><div><div class="eyebrow">MCA Project 5 · Measured simulation results</div><h1>Branch prediction,<br>explained by the results.</h1><p>Compare three ways to predict the next instruction address. Start with a loop, then explore patterns where learning helps and where it fails.</p><nav aria-label="Report sections"><a href="#comparison">Explore the results</a><a href="#walkthrough">Follow a branch</a><a href="#hardware">Hardware estimates</a><a href="#evidence">Verification</a><a href="../output/pdf/project_guide.pdf">Project guide PDF</a></nav></div></header>
<main>
<div class="stats"><div class="stat"><strong id="comparisons"></strong><span>RTL and reference comparisons</span></div><div class="stat"><strong id="workloads"></strong><span>Workloads tested with all strategies</span></div><div class="stat"><strong id="check-status"></strong><span>Recorded RTL verification status</span></div><div class="stat"><strong id="clock-target"></strong><span>FPGA timing target</span></div></div>
<section id="comparison"><h2>How much does prediction help?</h2><p class="muted">Each strategy sees the same trace and starts with cold tables. Correct next-address predictions include both direction and target correctness.</p>
<div class="toolbar"><div><label for="workload">Choose a workload</label><select id="workload"></select></div><button type="button" id="print">Print this report</button></div><p id="workload-meta" class="caption"></p><div class="cards" id="cards"></div><p id="insight" class="insight" aria-live="polite"></p><p id="pattern-note" class="muted"></p>
<details><summary>What do these measurements mean?</summary><div class="grid"><div><h3>Direction and target</h3><p>Direction asks whether a branch is taken. The target buffer remembers where to jump. A correct direction can still produce a wrong next address if its target is missing or stale.</p></div><div><h3>CPI and redirects</h3><p>A redirect corrects a wrong saved next address. Estimated cycles per instruction (CPI) adds the assumed recovery cost to base CPI. Lower is better. It is an analytical model, not measured CPU execution.</p></div></div></details></section>
<section id="walkthrough"><h2>Follow the first twelve branches</h2><p class="muted">“Correct” means the original next-address prediction matched the resolved address. “Redirect” means recovery was required. Change the workload above to compare another pattern.</p><div class="tablewrap"><table><thead><tr><th scope="col">Visit</th><th scope="col">Actual outcome</th><th scope="col">Always not taken</th><th scope="col">1-bit predictor</th><th scope="col">2-bit predictor</th></tr></thead><tbody id="trace"></tbody></table></div>
<details><summary>Show launch states and saved next addresses</summary><div id="trace-details"></div></details><p class="caption">The harness saves a prediction at issue edge N and resolves it at N+2. It allows one outstanding branch. State is updated only when the branch resolves.</p></section>
<section><h2>Read the full comparison</h2><p class="muted">The same strategies can behave very differently across workloads. An alternating pattern and target collisions are useful counterexamples.</p><div class="frame">@@ACCURACY@@</div><div class="frame">@@CPI@@</div></section>
<section><h2>What the hardware does</h2><p class="reading">The history table predicts taken or not taken. The target buffer supplies a remembered destination. Selection chooses that destination only when both agree that a usable taken prediction exists; otherwise it chooses PC + 4. Recovery compares the saved choice with the actual next address.</p><div class="frame">@@ARCHITECTURE@@</div><details><summary>Inspect the actual simulation waveform</summary><div class="frame">@@WAVEFORM@@</div><p class="caption">This preview is parsed from the recorded two-bit VCD. It shows the first loop exit and the next invocation.</p></details></section>
<section id="hardware"><h2>FPGA resource and timing estimates</h2><p class="muted">iCE40 HX8K CT256, fixed place-and-route seed 1. Full designs include prediction, recovery, and serial transport. The separate fixture reference is not an exact amount to subtract.</p><div class="tablewrap"><table><thead><tr><th scope="col">Configuration</th><th scope="col">Logic cells</th><th scope="col">RAM blocks</th><th scope="col">Estimated maximum MHz</th></tr></thead><tbody id="hardware-rows"></tbody></table></div><p class="caption">These are routed internal timing estimates from tools. They do not establish a board-tested operating frequency or processor throughput.</p></section>
<section id="evidence"><h2>Evidence you can inspect</h2><p id="verification-text"></p><p id="cpi-assumptions"></p><p><a href="accuracy.csv">Accuracy data CSV</a> · <a href="technical_report.md">Full technical report</a> · <a href="verification.json">RTL verification record</a> · <a href="synthesis/summary.csv">Synthesis data CSV</a></p><p>Run <code>make all</code> to regenerate the project evidence. Run <code>make demo</code> for the narrated console walkthrough.</p></section>
<div class="foot">Standalone Verilog branch prediction unit · No complete CPU is required for this implementation. All images and displayed data are embedded, so this page opens offline. Evidence links refer to files in the project folder.</div>
</main><script type="application/json" id="report-data">@@DATA@@</script>
<script>
const DATA=JSON.parse(document.getElementById('report-data').textContent);
const modes=Object.keys(DATA.strategies), $=id=>document.getElementById(id), number=x=>Number(x).toLocaleString('en-US'), percent=x=>(100*Number(x)).toFixed(2)+'%';
const cell=(tr,text,style)=>{const td=document.createElement('td');td.textContent=text;if(style)td.className=style;tr.appendChild(td)};
function draw(){const name=$('workload').value,w=DATA.workloads[name],first=w.rows[0];$('workload-meta').textContent=number(first.branches)+' branches · '+number(first.instructions)+' retired instructions · '+percent(first.branch_frequency)+' branch frequency';$('cards').replaceChildren();
for(const r of w.rows){const c=document.createElement('article');c.className='card '+r.strategy;const h=document.createElement('h3');h.textContent=DATA.strategies[r.strategy];c.appendChild(h);const m=document.createElement('div');m.className='metric';m.textContent=percent(r.next_address_accuracy);c.appendChild(m);const label=document.createElement('div');label.className='muted';label.textContent='correct next address';c.appendChild(label);const bar=document.createElement('div');bar.className='bar';const fill=document.createElement('i');fill.style.width=percent(r.next_address_accuracy);bar.appendChild(fill);c.appendChild(bar);const dl=document.createElement('dl');for(const [key,value] of [['Correct predictions',number(r.next_address_correct)+' / '+number(r.branches)],['Redirects',number(r.recoveries)],['Direction accuracy',percent(r.direction_accuracy)],['Target buffer hit rate',percent(r.btb_hit_rate)],['Estimated CPI',Number(r.estimated_cpi).toFixed(5)]]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=key;dd.textContent=value;dl.append(dt,dd)}c.appendChild(dl);$('cards').appendChild(c)}
const base=w.rows.find(r=>r.strategy==='always_not_taken'),two=w.rows.find(r=>r.strategy==='two_bit'),saved=Number(base.recoveries)-Number(two.recoveries);$('insight').textContent=saved>0?'The 2-bit predictor avoids '+number(saved)+' redirects compared with always not taken on this workload.':saved<0?'The 2-bit predictor needs '+number(-saved)+' more redirects than always not taken on this workload.':'The 2-bit predictor and always not taken require the same number of redirects on this workload.';
const notes={repeated_loop:'A one-bit predictor forgets the taken pattern at each loop exit. Two-bit prediction retains taken direction across one exit and predicts the next entry correctly.',alternating:'With these initial states, both dynamic predictors oscillate out of phase with the trace. Learning is not a universal win.',btb_collisions:'Both directions can be learned, but the branches repeatedly evict each other’s targets. High direction accuracy does not guarantee a correct next address.',bht_collisions:'The two addresses share a history entry. Opposite outcomes interfere in the same counter.',target_changes:'The direction stays taken while a previously stored target becomes stale. A correct direction can still require recovery.',always_not_taken:'The reset prediction already matches every outcome. All strategies correctly select sequential execution.',always_taken:'The first branch starts cold. Dynamic prediction learns the taken outcome and target after resolution.',nested_loops:'Different branch addresses have separate history entries, so inner and outer loops can learn independently.',biased_random:'The fixed-seed trace is mostly taken. Two-bit counters can tolerate some isolated not-taken outcomes.',operand_edges:'These traces exercise BEQ and BNE using 32-bit operand comparisons, including equality at boundary values.'};$('pattern-note').textContent=notes[name]||'';
$('trace').replaceChildren();for(let i=0;i<w.outcomes.length;i++){const tr=document.createElement('tr');cell(tr,i+1);cell(tr,w.outcomes[i]?'Taken':'Not taken');for(const mode of modes){const bad=Number(w.traces[mode][i].flush);cell(tr,bad?'Redirect':'Correct',bad?'bad':'good')}$('trace').appendChild(tr)}
$('trace-details').replaceChildren();for(const mode of modes){const h=document.createElement('h3');h.textContent=DATA.strategies[mode];const wrap=document.createElement('div');wrap.className='tablewrap';const table=document.createElement('table'),head=document.createElement('thead'),hr=document.createElement('tr');for(const label of ['Visit','State before update','Direction','Target buffer','Saved next address']){const th=document.createElement('th');th.scope='col';th.textContent=label;hr.appendChild(th)}head.appendChild(hr);table.appendChild(head);const body=document.createElement('tbody');for(let i=0;i<w.traces[mode].length;i++){const r=w.traces[mode][i],tr=document.createElement('tr');for(const value of [i+1,r.state_label,Number(r.predicted_taken)?'Taken':'Not taken',Number(r.btb_hit)?'Hit':'Miss','0x'+parseInt(r.predicted_next_pc,16).toString(16).toUpperCase().padStart(4,'0')])cell(tr,value);body.appendChild(tr)}table.appendChild(body);wrap.appendChild(table);$('trace-details').append(h,wrap)}}
for(const [key,w] of Object.entries(DATA.workloads)){const option=document.createElement('option');option.value=key;option.textContent=w.label;$('workload').appendChild(option)}$('workload').value=DATA.workloads.repeated_loop?'repeated_loop':Object.keys(DATA.workloads)[0];$('workload').addEventListener('change',draw);$('print').addEventListener('click',()=>window.print());
$('comparisons').textContent=number(DATA.verification.comparisons);$('workloads').textContent=number(DATA.verification.workloads);$('check-status').textContent=DATA.verification.status;$('check-status').className=DATA.verification.status==='PASS'?'status':'';$('clock-target').textContent=DATA.hardware.length?number(DATA.hardware[0].target_mhz)+' MHz':'Not run';
for(const r of DATA.hardware){const tr=document.createElement('tr');for(const v of [DATA.strategies[r.strategy]||'Serial fixture reference',number(r.logic_cells)+' / '+number(r.logic_cells_available),r.block_rams,Number(r.estimated_fmax_mhz).toFixed(2)])cell(tr,v);$('hardware-rows').appendChild(tr)}if(!DATA.hardware.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=4;td.textContent='Synthesis has not been run. Use make synthesis to generate hardware estimates.';tr.appendChild(td);$('hardware-rows').appendChild(tr)}
$('verification-text').textContent=number(DATA.verification.comparisons)+' branch predictions were checked field by field against the independent Python model across '+number(DATA.verification.workloads)+' workloads and '+number(DATA.verification.strategies)+' strategies. '+(DATA.units?'Directed RTL and Python checks are recorded as '+DATA.units.status+'.':'Directed test results are not available.');$('cpi-assumptions').textContent='CPI assumptions: base '+DATA.verification.base_cpi+', recovery penalty '+DATA.verification.recovery_penalty+' cycles. The harness clock count is not CPU CPI.';draw();
</script></body></html>'''
    for key, name, alt in [('ACCURACY','accuracy_comparison','Direction and next-address accuracy across ten workloads'),
                          ('CPI','cpi_comparison','Analytical CPI across ten workloads'),
                          ('ARCHITECTURE','architecture','Predictor and branch-resolution architecture'),
                          ('WAVEFORM','waveform_preview','Actual two-bit simulation waveform')]:
        html=html.replace('@@'+key+'@@',image(name,alt))
    html=html.replace('@@DATA@@',data)
    (ROOT/'reports/results.html').write_text(html)
    print('Readable results: reports/results.html (opens offline in any modern browser)')


if __name__=='__main__':
    build()
